package com.valor.auth;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.boot.test.mock.mockito.SpyBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.valor.notifications.NotificationService;
import com.valor.realtime.RealtimeEventService;

@SpringBootTest(properties = {"spring.datasource.url=jdbc:h2:mem:technician_reassignment_test;MODE=MySQL;DB_CLOSE_DELAY=-1;DB_CLOSE_ON_EXIT=FALSE"})
@AutoConfigureMockMvc @ActiveProfiles("test")
class TechnicianReassignmentTest {
    @Autowired MockMvc mvc; @Autowired ObjectMapper json; @Autowired UserRepo users; @Autowired CustomerRepo customers;
    @Autowired TechRepo technicians; @Autowired JwtService jwt; @Autowired JdbcTemplate db; @Autowired EntityManager em;
    @Autowired NotificationService notificationService; @SpyBean RealtimeEventService realtime;

    record Fixture(User admin, User superAdmin, User customer, User technician, TechnicianProfile profile, long requestId) {}
    private User user(Role role) { User u=new User(); u.setEmail(UUID.randomUUID()+"@example.test"); u.setRole(role); return users.saveAndFlush(u); }
    private TechnicianProfile tech() { TechnicianProfile t=new TechnicianProfile(); t.user=user(Role.TECHNICIAN); return technicians.saveAndFlush(t); }
    private JsonNode call(MockHttpServletRequestBuilder request, User actor, Object body, int expected) throws Exception {
        if(actor!=null) request.header("Authorization","Bearer "+jwt.issue(actor));
        if(body!=null) request.contentType("application/json").content(json.writeValueAsString(body));
        String text=mvc.perform(request).andExpect(status().is(expected)).andReturn().getResponse().getContentAsString();
        JsonNode envelope=json.readTree(text); assertEquals(expected<400,envelope.get("success").asBoolean(),text); return envelope.get("data");
    }
    private Fixture fixture() throws Exception {
        User admin=user(Role.ADMIN), superAdmin=user(Role.SUPER_ADMIN), customer=user(Role.CUSTOMER); CustomerProfile cp=new CustomerProfile(); cp.setUser(customer); cp.setFullName("Reassignment customer"); customers.saveAndFlush(cp);
        TechnicianProfile t=tech(); long building=call(post("/api/v1/buildings"),admin,Map.of("customerProfileId",cp.getId(),"buildingName","Tower","latitude",17.385044,"longitude",78.486671),200).get("id").asLong();
        long lift=call(post("/api/v1/lifts"),admin,Map.of("buildingId",building,"name","Lift"),200).get("id").asLong();
        long request=call(post("/api/v1/service-requests"),customer,Map.of("liftId",lift,"title","Breakdown","description","Door issue","serviceType","BREAKDOWN"),200).at("/request/id").asLong();
        return new Fixture(admin,superAdmin,customer,t.getUser(),t,request);
    }
    private String base(Fixture f){return "/api/v1/service-requests/"+f.requestId();}
    private long assign(Fixture f,long profileId) throws Exception { return call(post(base(f)+"/assignments"),f.admin(),Map.of("technicianProfileId",profileId,"notes","Initial"),200).at("/activeAssignment/id").asLong(); }
    private long request(Fixture f,User actor,Object body,int expected) throws Exception { return call(post("/api/v1/technician/me/jobs/"+f.requestId()+"/reassignment-requests"),actor,body,expected).path("id").asLong(); }
    private Map<String,Object> valid(){return Map.of("reasonCode","WORKLOAD","reasonExplanation","I cannot safely continue this job during the current shift.");}

    @Test void activeAssigneeCanCreateDuplicateIsRejectedAndOriginalRemainsActive() throws Exception {
        Fixture f=fixture(); long assignment=assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); assertTrue(id>0);
        assertEquals(409, mvc.perform(post("/api/v1/technician/me/jobs/"+f.requestId()+"/reassignment-requests").header("Authorization","Bearer "+jwt.issue(f.technician())).contentType("application/json").content(json.writeValueAsString(valid()))).andReturn().getResponse().getStatus());
        assertEquals("ASSIGNED",db.queryForObject("select status from technician_assignments where id=?",String.class,assignment)); assertEquals("ASSIGNED",db.queryForObject("select status from service_requests where id=?",String.class,f.requestId()));
    }
    @Test void nonOwnersAndUnassignedTechniciansAreDenied() throws Exception {
        Fixture f=fixture(); TechnicianProfile other=tech(); request(f,other.getUser(),valid(),403); request(f,f.technician(),valid(),403);
    }
    @Test void validationRejectsBlankReasonAndInvalidEnum() throws Exception {
        Fixture f=fixture(); assign(f,f.profile().getId()); request(f,f.technician(),Map.of("reasonCode","WORKLOAD","reasonExplanation","   "),400); request(f,f.technician(),Map.of("reasonCode","NOT_A_REASON","reasonExplanation","explanation"),400);
    }
    @Test void handoverIsOptionalBeforeSiteAndRequiredAtSite() throws Exception {
        Fixture f=fixture(); assign(f,f.profile().getId()); request(f,f.technician(),valid(),200); Fixture later=fixture(); assign(later,later.profile().getId()); db.update("update service_requests set status='REACHED_SITE' where id=?",later.requestId()); request(later,later.technician(),valid(),400); Map<String,Object> body=new HashMap<>(valid()); body.put("handover",Map.of("workCompleted","Safety check done","workPending","Repair pending")); request(later,later.technician(),body,200);
    }
    @Test void technicianCanListAndWithdrawOnlyOwnPendingRequest() throws Exception {
        Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); JsonNode page=call(get("/api/v1/technician/me/jobs/"+f.requestId()+"/reassignment-requests"),f.technician(),null,200); assertEquals(id,page.at("/items/0/id").asLong()); call(post("/api/v1/technician/me/reassignment-requests/"+id+"/withdraw"),f.technician(),null,200); assertEquals("WITHDRAWN",db.queryForObject("select status from technician_reassignment_requests where id=?",String.class,id)); assertEquals(409,mvc.perform(post("/api/v1/technician/me/reassignment-requests/"+id+"/withdraw").header("Authorization","Bearer "+jwt.issue(f.technician()))).andReturn().getResponse().getStatus());
    }
    @Test void adminCanListInspectRejectAndCannotBeTechnicianOrCustomer() throws Exception {
        Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); JsonNode page=call(get("/api/v1/admin/reassignment-requests?status=PENDING&page=0&size=10"),f.admin(),null,200); assertEquals(id,page.at("/items/0/id").asLong()); assertEquals(id,call(get("/api/v1/admin/reassignment-requests/"+id),f.superAdmin(),null,200).get("id").asLong()); request(f,f.customer(),valid(),403); call(post("/api/v1/admin/reassignment-requests/"+id+"/reject"),f.admin(),Map.of("reason","Not operationally justified"),200); assertEquals("REJECTED",db.queryForObject("select status from technician_reassignment_requests where id=?",String.class,id)); assertEquals("ASSIGNED",db.queryForObject("select status from technician_assignments where service_request_id=?",String.class,f.requestId()));
    }
    @Test void rejectionRequiresDecisionReason() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); call(post("/api/v1/admin/reassignment-requests/"+id+"/reject"),f.admin(),Map.of("reason"," "),400); }
    @Test void approvalTransfersAtomicallyAndPreservesJobStatus() throws Exception {
        Fixture f=fixture(); long old=assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); TechnicianProfile replacement=tech(); JsonNode result=call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",replacement.getId(),"decisionReason","Capacity handover approved"),200); assertEquals("TRANSFERRED",result.at("/status").asText()); assertEquals("TRANSFERRED",call(get("/api/v1/technician/me/jobs/"+f.requestId()+"/reassignment-requests"),f.technician(),null,200).at("/items/0/status").asText()); assertEquals("ASSIGNED",db.queryForObject("select status from service_requests where id=?",String.class,f.requestId())); assertEquals("RELEASED",db.queryForObject("select status from technician_assignments where id=?",String.class,old)); assertEquals(1,db.queryForObject("select count(*) from technician_assignments where service_request_id=? and status in ('ASSIGNED','ACCEPTED')",Integer.class,f.requestId())); assertEquals(1,db.queryForObject("select count(*) from technician_assignments where service_request_id=? and status='ASSIGNED'",Integer.class,f.requestId())); assertEquals(old,db.queryForObject("select original_assignment_id from technician_reassignment_requests where id=?",Long.class,id)); assertEquals(f.admin().getId(),db.queryForObject("select reviewed_by_user_id from technician_reassignment_requests where id=?",Long.class,id)); assertEquals(403,mvc.perform(post(base(f)+"/assignments/"+old+"/accept").header("Authorization","Bearer "+jwt.issue(f.technician()))).andReturn().getResponse().getStatus()); assertEquals(0,call(get("/api/v1/technician/me/jobs/"+f.requestId()+"/reassignment-requests"),replacement.getUser(),null,200).at("/items").size());
    }
    @Test void outgoingCannotApproveAgainOrBeSelectedAsReplacement() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); TechnicianProfile replacement=tech(); long id=request(f,f.technician(),valid(),200); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",f.profile().getId()),400); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",replacement.getId()),200); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",f.profile().getId()),409); }
    @Test void inactiveReplacementAndStaleOriginalAssignmentAreRejected() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); TechnicianProfile inactive=tech(); db.update("update technician_profiles set is_active=false where id=?",inactive.getId()); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",inactive.getId()),400); Fixture stale=fixture(); assign(stale,stale.profile().getId()); long staleId=request(stale,stale.technician(),valid(),200); TechnicianProfile other=tech(); assign(stale,other.getId()); call(post("/api/v1/admin/reassignment-requests/"+staleId+"/approve"),stale.admin(),Map.of("replacementTechnicianProfileId",tech().getId()),409); }
    @Test void assignmentHistoryExposesRetainedRowsOnlyToAdmin() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); TechnicianProfile replacement=tech(); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",replacement.getId()),200); JsonNode history=call(get("/api/v1/admin/service-requests/"+f.requestId()+"/assignment-history"),f.admin(),null,200); assertEquals(2,history.size()); assertEquals(403,mvc.perform(get("/api/v1/admin/service-requests/"+f.requestId()+"/assignment-history").header("Authorization","Bearer "+jwt.issue(f.customer()))).andReturn().getResponse().getStatus()); }
    @Test void requesterCanReadRejectedAndCancelledHistory() throws Exception { Fixture rejected=fixture(); assign(rejected,rejected.profile().getId()); long rejectedId=request(rejected,rejected.technician(),valid(),200); call(post("/api/v1/admin/reassignment-requests/"+rejectedId+"/reject"),rejected.admin(),Map.of("reason","Coverage is available"),200); assertEquals("REJECTED",call(get("/api/v1/technician/me/jobs/"+rejected.requestId()+"/reassignment-requests"),rejected.technician(),null,200).at("/items/0/status").asText()); Fixture cancelled=fixture(); assign(cancelled,cancelled.profile().getId()); long cancelledId=request(cancelled,cancelled.technician(),valid(),200); call(post("/api/v1/admin/reassignment-requests/"+cancelledId+"/cancel"),cancelled.admin(),Map.of("reason","Job no longer requires transfer"),200); assertEquals("CANCELLED",call(get("/api/v1/technician/me/jobs/"+cancelled.requestId()+"/reassignment-requests"),cancelled.technician(),null,200).at("/items/0/status").asText()); }
    @Test void transferredRequestCannotBeWithdrawnByFormerRequester() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); TechnicianProfile replacement=tech(); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",replacement.getId()),200); assertEquals(409,mvc.perform(post("/api/v1/technician/me/reassignment-requests/"+id+"/withdraw").header("Authorization","Bearer "+jwt.issue(f.technician()))).andReturn().getResponse().getStatus()); }
    @Test void terminalJobsCannotReceiveRequests() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); db.update("update service_requests set status='COMPLETED' where id=?",f.requestId()); request(f,f.technician(),valid(),409); }
    @Test void successfulTransferCreatesExactlyTwoIdempotentNotifications() throws Exception { Fixture f=fixture(); assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); TechnicianProfile replacement=tech(); call(post("/api/v1/admin/reassignment-requests/"+id+"/approve"),f.admin(),Map.of("replacementTechnicianProfileId",replacement.getId()),200); assertEquals(2,db.queryForObject("select count(*) from notifications where event_key in (?,?)",Integer.class,"reassignment:"+id+":incoming","reassignment:"+id+":outgoing")); notificationService.createSystemOnce(replacement.getUser().getId(),"reassignment:"+id+":incoming","ignored","ignored"); notificationService.createSystemOnce(f.technician().getId(),"reassignment:"+id+":outgoing","ignored","ignored"); assertEquals(2,db.queryForObject("select count(*) from notifications where event_key in (?,?)",Integer.class,"reassignment:"+id+":incoming","reassignment:"+id+":outgoing")); }
    @Test void failedTransferRollsBackAssignmentRequestAuditNotificationsAndRealtime() throws Exception { Fixture f=fixture(); long old=assign(f,f.profile().getId()); long id=request(f,f.technician(),valid(),200); TechnicianProfile replacement=tech(); doThrow(new IllegalStateException("forced transfer failure")).when(realtime).publish(eq("JOB_ASSIGNMENT_CHANGED"),eq("SERVICE_REQUEST"),eq(f.requestId()),anyString(),anySet()); clearInvocations(realtime); mvc.perform(post("/api/v1/admin/reassignment-requests/"+id+"/approve").header("Authorization","Bearer "+jwt.issue(f.admin())).contentType("application/json").content(json.writeValueAsString(Map.of("replacementTechnicianProfileId",replacement.getId())))).andExpect(status().is5xxServerError()); assertEquals("ASSIGNED",db.queryForObject("select status from technician_assignments where id=?",String.class,old)); assertEquals(1,db.queryForObject("select count(*) from technician_assignments where service_request_id=? and status in ('ASSIGNED','ACCEPTED')",Integer.class,f.requestId())); assertEquals("PENDING",db.queryForObject("select status from technician_reassignment_requests where id=?",String.class,id)); assertEquals(0,db.queryForObject("select count(*) from notifications where event_key like ?",Integer.class,"reassignment:"+id+":%")); assertEquals(0,db.queryForObject("select count(*) from audit_logs where entity_type='TECHNICIAN_REASSIGNMENT_REQUEST' and entity_id=? and action='TECHNICIAN_REASSIGNMENT_TRANSFER'",Integer.class,id)); verify(realtime, times(1)).publish(eq("JOB_ASSIGNMENT_CHANGED"),eq("SERVICE_REQUEST"),eq(f.requestId()),anyString(),anySet()); }
    @Test void adminDirectAssignmentPersistsReasonAndCancelsPendingRequest() throws Exception { Fixture f=fixture(); long old=assign(f,f.profile().getId()); long requestId=request(f,f.technician(),valid(),200); TechnicianProfile replacement=tech(); String reason="Admin emergency coverage transfer"; call(post(base(f)+"/assignments"),f.admin(),Map.of("technicianProfileId",replacement.getId(),"notes",reason),200); assertEquals("CANCELLED",db.queryForObject("select status from technician_reassignment_requests where id=?",String.class,requestId)); assertEquals(reason,db.queryForObject("select decision_reason from technician_reassignment_requests where id=?",String.class,requestId)); assertEquals("RELEASED",db.queryForObject("select status from technician_assignments where id=?",String.class,old)); assertEquals(reason,db.queryForObject("select notes from technician_assignments where service_request_id=? and technician_id=?",String.class,f.requestId(),replacement.getId())); assertEquals(1,db.queryForObject("select count(*) from technician_assignments where service_request_id=? and status in ('ASSIGNED','ACCEPTED')",Integer.class,f.requestId())); }
}
